    ('a-league-2025-26-player-game-071-01-plunkett-walsh-v-steve-cooke', 71, 'Week 18', 'Grange A', 6, 'Newlands A', 1, 1, 1, false, 'Plunkett Walsh', 'Steve Cooke', 1),
    ('a-league-2025-26-player-game-071-02-john-butler-v-graham-mchugh', 71, 'Week 18', 'Grange A', 6, 'Newlands A', 1, 2, 2, false, 'John Butler', 'Graham McHugh', 0),
    ('a-league-2025-26-player-game-071-03-ger-gormley-v-jimmy-harlow', 71, 'Week 18', 'Grange A', 6, 'Newlands A', 1, 3, 3, false, 'Ger Gormley', 'Jimmy Harlow', 1),
    ('a-league-2025-26-player-game-071-04-dave-sweetman-v-mark-carroll', 71, 'Week 18', 'Grange A', 6, 'Newlands A', 1, 3, 4, true, 'Dave Sweetman', 'Mark Carroll', 1),
    ('a-league-2025-26-player-game-071-05-alan-cooke-v-conor-faughnan', 71, 'Week 18', 'Grange A', 6, 'Newlands A', 1, 4, 5, false, 'Alan Cooke', 'Conor Faughnan', 1),
    ('a-league-2025-26-player-game-071-06-rob-buckley-v-damien-long', 71, 'Week 18', 'Grange A', 6, 'Newlands A', 1, 5, 6, false, 'Rob Buckley', 'Damien Long', 1),
    ('a-league-2025-26-player-game-071-07-mick-mcdermott-v-maurice-ebbs', 71, 'Week 18', 'Grange A', 6, 'Newlands A', 1, 6, 7, false, 'Mick McDermott', 'Maurice Ebbs', 1)
),
player_lookup as (
  select
    lower(sp.full_name) as full_name_key,
    min(p.id::text)::uuid as person_id
  from source_players sp
  join public.person p
    on lower(p.first_name) = lower(sp.first_name)
   and lower(p.last_name) = lower(sp.last_name)
  group by lower(sp.full_name)
),
resolved_games as (
  select
    sg.*,
    s.id as season_id,
    l.id as league_id,
    p1.person_id as player_1_id,
    p2.person_id as player_2_id
  from source_games sg
  join public.season s on s.name = '2025/26'
  join public.league l on l.name = 'A League'
  join player_lookup p1 on p1.full_name_key = lower(sg.player_1_name)
  join player_lookup p2 on p2.full_name_key = lower(sg.player_2_name)
)
insert into public.player_game_result (
  season_id, league_id, source_fixture_index, source_week, home_team_name, home_team_score, away_team_name, away_team_score,
  game_number, game_ordinal, is_doubles_partner_row, player_1_id, player_2_id, result, source_key
)
select
  season_id, league_id, source_fixture_index, source_week, home_team_name, home_team_score, away_team_name, away_team_score,
  game_number, game_ordinal, is_doubles_partner_row, player_1_id, player_2_id, result, source_key
from resolved_games
on conflict (source_key) do update
set result = excluded.result,
    game_number = excluded.game_number,
    game_ordinal = excluded.game_ordinal,
    is_doubles_partner_row = excluded.is_doubles_partner_row,
    player_1_id = excluded.player_1_id,
    player_2_id = excluded.player_2_id;
